#include <cmath>

struct Vector2 { float x, y; };

Vector2 inputDirection(bool up, bool down, bool left, bool right) { return { 0, 0 }; }
float clampDt(float dt) { return dt; }
void step(Vector2& pos, Vector2& vel, Vector2 accel, float drag, float dt) {}

class Shooter
{
public:
    explicit Shooter(float period) {}
    int update(bool fireHeld, float dt) { return 0; }
};

solution.solution.cpp:
#include <algorithm>
#include <cmath>

struct Vector2 { float x, y; };

Vector2 inputDirection(bool up, bool down, bool left, bool right)
{
    Vector2 d{ static_cast<float>(right) - static_cast<float>(left), static_cast<float>(down) - static_cast<float>(up) };
    const float len{ std::sqrt(d.x * d.x + d.y * d.y) };
    if (len > 0) { d.x /= len; d.y /= len; }
    return d;
}

float clampDt(float dt)
{
    return std::clamp(dt, 0.0f, 0.05f);
}

void step(Vector2& pos, Vector2& vel, Vector2 accel, float drag, float dt)
{
    vel.x += accel.x * dt;
    vel.y += accel.y * dt;
    const float keep{ std::pow(drag, dt) };
    vel.x *= keep;
    vel.y *= keep;
    pos.x += vel.x * dt;
    pos.y += vel.y * dt;
}

class Shooter
{
public:
    explicit Shooter(float period) : m_period{ period } {}

    int update(bool fireHeld, float dt)
    {
        m_cooldown -= dt;
        int shots{ 0 };
        if (fireHeld)
            while (m_cooldown <= 0) { ++shots; m_cooldown += m_period; }
        else if (m_cooldown < 0)
            m_cooldown = 0;
        return shots;
    }

private:
    float m_period;
    float m_cooldown{ 0 };
};

unitTests:
TEST("directions") {
    Vector2 d = inputDirection(false, false, false, true); CHECK_NEAR(d.x, 1.0, 1e-5); CHECK_NEAR(d.y, 0.0, 1e-5);
    d = inputDirection(true, false, false, true); CHECK_NEAR(d.x, 0.70711, 1e-4); CHECK_NEAR(d.y, -0.70711, 1e-4);
    d = inputDirection(true, true, true, true); CHECK_NEAR(d.x, 0.0, 1e-5); CHECK_NEAR(d.y, 0.0, 1e-5);
}
TEST("clamp dt") { CHECK_NEAR(clampDt(0.016f), 0.016, 1e-6); CHECK_NEAR(clampDt(1.5f), 0.05, 1e-6); CHECK_NEAR(clampDt(-1), 0.0, 1e-6); }
TEST("step without drag") { Vector2 p{ 0, 0 }, v{ 10, 0 }; step(p, v, { 0, 100 }, 1.0f, 0.5f); CHECK_NEAR(v.y, 50.0, 1e-4); CHECK_NEAR(p.y, 25.0, 1e-4); CHECK_NEAR(p.x, 5.0, 1e-4); }
TEST("drag is per second") {
    Vector2 p1{ 0, 0 }, v1{ 100, 0 }; for (int i = 0; i < 60; ++i) step(p1, v1, { 0, 0 }, 0.5f, 1.0f / 60);
    Vector2 p2{ 0, 0 }, v2{ 100, 0 }; for (int i = 0; i < 30; ++i) step(p2, v2, { 0, 0 }, 0.5f, 1.0f / 30);
    CHECK_NEAR(v1.x, 50.0, 1e-2); CHECK_NEAR(v2.x, 50.0, 1e-2);
}
TEST("shooter") {
    Shooter s{ 0.25f };
    CHECK_EQ(s.update(true, 0.1f), 1); CHECK_EQ(s.update(true, 0.1f), 0); CHECK_EQ(s.update(true, 0.1f), 1);
    CHECK_EQ(s.update(true, 0.6f), 2);
    Shooter t{ 0.25f }; t.update(true, 0.0f); t.update(false, 5.0f); CHECK_EQ(t.update(true, 0.0f), 1); CHECK_EQ(t.update(true, 0.0f), 0);
}

